package main

import "fmt"

// ReverseInPlace reverses the elements of an integer slice in place.
func ReverseInPlace(s []int) {
    // Initialize two pointers: one at the start and one at the end.
    left := 0
    right := len(s) - 1

    // Continue swapping elements until the pointers meet or cross.
    for left < right {
        // 1. Swap the elements at the left and right indices
        s[left], s[right] = s[right], s[left]

        // 2. Move the pointers inward
        left++
        right--
    }
}

